initJs:
function(container, apiUrl, tables) {
  let currentModelData = null;
  let currentExecutionId = null;
  let progressInterval = null;

  // DOM要素の取得
  const modelSelect = container.querySelector('#model-select');
  const modelDetails = container.querySelector('#model-details');
  const modelInfo = container.querySelector('#model-info');
  const storeList = container.querySelector('#store-list');
  const selectAllStores = container.querySelector('#select-all-stores');
  const startDatetime = container.querySelector('#start-datetime');
  const backupEnabled = container.querySelector('#backup-enabled');
  const retentionDays = container.querySelector('#retention-days');
  const validationResults = container.querySelector('#validation-results');
  const validationInfo = container.querySelector('#validation-info');
  const impactAnalysis = container.querySelector('#impact-analysis');
  const impactInfo = container.querySelector('#impact-info');
  const btnExecute = container.querySelector('#btn-execute');
  const btnValidate = container.querySelector('#btn-validate');
  const btnRollback = container.querySelector('#btn-rollback');
  const progressSection = container.querySelector('#progress-section');
  const progressBar = container.querySelector('#progress-bar');
  const progressText = container.querySelector('#progress-text');
  const progressStatus = container.querySelector('#progress-status');
  const logSection = container.querySelector('#log-section');
  const logDisplay = container.querySelector('#log-display');
  const errorMessage = container.querySelector('#error-message');

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // ログ追加関数
  function addLog(message) {
    const timestamp = new Date().toLocaleString();
    logDisplay.textContent += `[${timestamp}] ${message}\n`;
    logDisplay.scrollTop = logDisplay.scrollHeight;
  }

  // 進捗更新関数
  function updateProgress(percent, status) {
    progressBar.style.width = `${percent}%`;
    progressText.textContent = `${percent}%`;
    progressStatus.textContent = status;
  }

  // モデル一覧の初期化
  async function initializeModels() {
    try {
      // サンプルモデルデータを生成
      const models = [
        {
          id: 'model-001',
          name: 'AI需要予測モデル v2.1',
          version: '2.1.0',
          accuracy: 92.5,
          status: '検証済み',
          createdAt: '2024-01-15T10:30:00',
          description: '季節要因と天候データを考慮した高精度予測モデル'
        },
        {
          id: 'model-002',
          name: 'AI需要予測モデル v2.0',
          version: '2.0.0',
          accuracy: 89.3,
          status: '本番適用中',
          createdAt: '2024-01-10T14:20:00',
          description: '基本的な需要予測機能を提供するモデル'
        }
      ];

      modelSelect.innerHTML = '<option value="">-- モデルを選択してください --</option>';
      models.forEach(model => {
        const option = document.createElement('option');
        option.value = model.id;
        option.textContent = `${model.name} (精度: ${model.accuracy}%)`;
        option.dataset.modelData = JSON.stringify(model);
        modelSelect.appendChild(option);
      });
    } catch (error) {
      showError('モデル一覧の取得に失敗しました');
    }
  }

  // 店舗一覧の初期化
  async function initializeStores() {
    try {
      const stores = await window.aivicApi.list(1) || tables[1]?.records || [];

      storeList.innerHTML = '';
      stores.forEach(store => {
        const div = document.createElement('div');
        div.style.marginBottom = '8px';
        div.innerHTML = `
          <label style="color: var(--text); cursor: pointer;">
            <input type="checkbox" class="store-checkbox" value="${store.id}" style="margin-right: 8px;">
            ${store.店舗名 || store.storeName || `店舗${store.id}`} (${store.店舗コード || store.storeCode || store.id})
          </label>
        `;
        storeList.appendChild(div);
      });
    } catch (error) {
      showError('店舗一覧の取得に失敗しました');
    }
  }

  // モデル選択時の処理
  modelSelect.addEventListener('change', function() {
    const selectedOption = this.options[this.selectedIndex];
    if (selectedOption.value && selectedOption.dataset.modelData) {
      currentModelData = JSON.parse(selectedOption.dataset.modelData);

      // モデル詳細情報を表示
      modelInfo.innerHTML = `
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px;">
          <div><strong>モデル名:</strong> ${currentModelData.name}</div>
          <div><strong>バージョン:</strong> ${currentModelData.version}</div>
          <div><strong>予測精度:</strong> ${currentModelData.accuracy}%</div>
          <div><strong>ステータス:</strong> ${currentModelData.status}</div>
          <div><strong>作成日時:</strong> ${new Date(currentModelData.createdAt).toLocaleString()}</div>
          <div style="grid-column: 1 / -1;"><strong>説明:</strong> ${currentModelData.description}</div>
        </div>
      `;
      modelDetails.style.display = 'block';

      // 検証ボタンを有効化
      btnValidate.disabled = false;
    } else {
      currentModelData = null;
      modelDetails.style.display = 'none';
      validationResults.style.display = 'none';
      impactAnalysis.style.display = 'none';
      btnValidate.disabled = true;
      btnExecute.disabled = true;
    }
  });

  // 全店舗選択チェックボックスの処理
  selectAllStores.addEventListener('change', function() {
    const checkboxes = container.querySelectorAll('.store-checkbox');
    checkboxes.forEach(checkbox => {
      checkbox.checked = this.checked;
    });
  });

  // 適用前検証実行
  btnValidate.addEventListener('click', async function() {
    if (!currentModelData) {
      showError('モデルが選択されていません');
      return;
    }

    try {
      btnValidate.disabled = true;
      btnValidate.textContent = '検証中...';

      // 検証処理をシミュレート
      await new Promise(resolve => setTimeout(resolve, 2000));

      // 検証結果を表示
      const validationPassed = Math.random() > 0.2; // 80%の確率で成功

      validationInfo.innerHTML = `
        <div style="margin-bottom: 15px;">
          <div style="display: flex; align-items: center; margin-bottom: 10px;">
            <span style="color: ${validationPassed ? '#4CAF50' : '#f44336'}; font-weight: bold;">
              ${validationPassed ? '✓ 検証成功' : '✗ 検証失敗'}
            </span>
          </div>
          <div style="margin-bottom: 10px;"><strong>データ品質チェック:</strong> ${validationPassed ? '正常' : 'エラー検出'}</div>
          <div style="margin-bottom: 10px;"><strong>精度閾値チェック:</strong> ${validationPassed ? '基準値クリア' : '基準値未達'}</div>
          <div style="margin-bottom: 10px;"><strong>互換性チェック:</strong> ${validationPassed ? '問題なし' : '互換性エラー'}</div>
        </div>
      `;

      validationResults.style.display = 'block';

      if (validationPassed) {
        // 影響範囲分析を表示
        const selectedStores = container.querySelectorAll('.store-checkbox:checked');
        impactInfo.innerHTML = `
          <div>
            <div style="margin-bottom: 10px;"><strong>対象店舗数:</strong> ${selectedStores.length}店舗</div>
            <div style="margin-bottom: 10px;"><strong>予想処理時間:</strong> 約${Math.ceil(selectedStores.length * 0.5)}分</div>
            <div style="margin-bottom: 10px;"><strong>影響する予測対象商品:</strong> 約${selectedStores.length * 150}商品</div>
            <div style="margin-bottom: 10px;"><strong>システム負荷:</strong> 中程度</div>
          </div>
        `;
        impactAnalysis.style.display = 'block';
        btnExecute.disabled = false;
      } else {
        impactAnalysis.style.display = 'none';
        btnExecute.disabled = true;
      }

    } catch (error) {
      showError('検証処理でエラーが発生しました');
    } finally {
      btnValidate.disabled = false;
      btnValidate.textContent = '適用前検証実行';
    }
  });

  // 適用実行処理
  btnExecute.addEventListener('click', async function() {
    // バリデーション
    if (!currentModelData) {
      showError('モデルが選択されていません');
      return;
    }

    const selectedStores = container.querySelectorAll('.store-checkbox:checked');
    if (selectedStores.length === 0) {
      showError('店舗が選択されていません');
      return;
    }

    const startTime = startDatetime.value;
    if (!startTime) {
      showError('適用開始日時が未入力です');
      return;
    }

    const startDate = new Date(startTime);
    const now = new Date();
    if (startDate < now) {
      showError('適用開始日時には現在日時以降を指定してください');
      return;
    }

    if (!confirm(`${currentModelData.name} を ${selectedStores.length}店舗に適用しますか？`)) {
      return;
    }

    try {
      btnExecute.disabled = true;
      btnExecute.textContent = '適用中...';
      progressSection.style.display = 'block';
      logSection.style.display = 'block';

      currentExecutionId = 'exec-' + Date.now();

      addLog('モデル本番適用処理を開始しました');
      addLog(`対象モデル: ${currentModelData.name}`);
      addLog(`対象店舗数: ${selectedStores.length}店舗`);
      addLog(`バックアップ設定: ${backupEnabled.checked ? '有効' : '無効'}`);

      // 進捗シミュレーション
      const steps = [
        { percent: 10, status: 'モデル検証中...', delay: 1000 },
        { percent: 25, status: 'バックアップ作成中...', delay: 1500 },
        { percent: 40, status: 'モデルデプロイ中...', delay: 2000 },
        { percent: 60, status: '店舗別設定適用中...', delay: 2500 },
        { percent: 80, status: '動作確認中...', delay: 1500 },
        { percent: 100, status: '適用完了', delay: 1000 }
      ];

      for (const step of steps) {
        await new Promise(resolve => setTimeout(resolve, step.delay));
        updateProgress(step.percent, step.status);
        addLog(step.status);
      }

      addLog('モデル本番適用処理が正常に完了しました');
      btnRollback.disabled = false;

    } catch (error) {
      showError('適用処理中にシステムエラーが発生しました');
      addLog(`エラー: ${error.message}`);
    } finally {
      btnExecute.disabled = false;
      btnExecute.textContent = '適用実行';
    }
  });

  // ロールバック実行処理
  btnRollback.addEventListener('click', async function() {
    if (!confirm('前のバージョンにロールバックしますか？')) {
      return;
    }

    try {
      btnRollback.disabled = true;
      btnRollback.textContent = 'ロールバック中...';

      addLog('ロールバック処理を開始しました');

      // ロールバック進捗シミュレーション
      const rollbackSteps = [
        { percent: 20, status: 'バックアップ確認中...', delay: 1000 },
        { percent: 50, status: '前バージョン復元中...', delay: 1500 },
        { percent: 80, status: '動作確認中...', delay: 1000 },
        { percent: 100, status: 'ロールバック完了', delay: 500 }
      ];

      for (const step of rollbackSteps) {
        await new Promise(resolve => setTimeout(resolve, step.delay));
        updateProgress(step.percent, step.status);
        addLog(step.status);
      }

      addLog('ロールバック処理が正常に完了しました');

    } catch (error) {
      showError('ロールバック処理でエラーが発生しました');
      addLog(`エラー: ${error.message}`);
    } finally {
      btnRollback.disabled = false;
      btnRollback.textContent = 'ロールバック実行';
    }
  });

  // 現在時刻を適用開始日時のデフォルト値に設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  startDatetime.value = now.toISOString().slice(0, 16);

  // 初期化
  initializeModels();
  initializeStores();
}
